<?php declare(strict_types=1); $this->layout('layouts/default', ['title' => $title, 'currentPage' => 'users']); $editing = is_array($user); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">GESTÃO DE ACESSO</p><h2><?= $this->e($title) ?></h2><p><?= $editing ? 'Atualize os dados e o nível de acesso desta conta.' : 'Crie uma conta com acesso definido explicitamente.' ?></p></div><a class="studio-btn" href="/studio/users">Voltar</a></header>
<form class="studio-form-card studio-user-form" method="post" action="/studio/users/save"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= $this->e((string) ($user['id'] ?? 0)) ?>"><div class="studio-form-grid"><div class="studio-field"><label for="name">Nome</label><input id="name" name="name" value="<?= $this->e((string) ($user['name'] ?? '')) ?>" minlength="2" maxlength="120" required></div><div class="studio-field"><label for="email">E-mail</label><input id="email" type="email" name="email" value="<?= $this->e((string) ($user['email'] ?? '')) ?>" maxlength="190" required></div><div class="studio-field"><label for="role">Perfil</label><select id="role" name="role"<?= (int) ($user['id'] ?? 0) === 1 ? ' disabled' : '' ?>><option value="user"<?= ($user['role'] ?? '') === 'user' ? ' selected' : '' ?>>Usuário</option><option value="admin"<?= ($user['role'] ?? '') === 'admin' ? ' selected' : '' ?>>Administrador</option></select><?php if ((int) ($user['id'] ?? 0) === 1): ?><input type="hidden" name="role" value="admin"><small>O administrador principal não pode ser rebaixado.</small><?php endif; ?></div><div class="studio-field"><label for="status">Status</label><select id="status" name="status"<?= (int) ($user['id'] ?? 0) === 1 ? ' disabled' : '' ?>><option value="active"<?= ($user['status'] ?? 'active') === 'active' ? ' selected' : '' ?>>Ativo</option><option value="inactive"<?= ($user['status'] ?? '') === 'inactive' ? ' selected' : '' ?>>Inativo</option></select><?php if ((int) ($user['id'] ?? 0) === 1): ?><input type="hidden" name="status" value="active"><?php endif; ?></div></div><div class="studio-field"><label for="password"><?= $editing ? 'Nova senha' : 'Senha' ?></label><input id="password" type="password" name="password" minlength="8" autocomplete="new-password"<?= $editing ? '' : ' required' ?>><small><?= $editing ? 'Deixe vazio para manter a senha atual.' : 'Use ao menos 8 caracteres.' ?></small></div><button type="submit">Salvar usuário</button></form>
<?php if ($editing && (int) $user['id'] !== 1): ?><form class="studio-danger-zone" method="post" action="/studio/users/action" data-confirm-submit="Excluir esta conta permanentemente?"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= $this->e((string) $user['id']) ?>"><input type="hidden" name="action" value="delete"><button class="studio-btn danger" type="submit">Excluir usuário</button></form><?php endif; ?></section>
